// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import java.lang.foreign.MemorySegment;

/**
 * Temporary Pass-1 build counters for the base builder (plan 27): one occupancy bitmap plus four u32 plane counts per
 * 4,096-slot value-ID page, allocated lazily per touched page in a dedicated {@code BUILD_COUNTERS} arena and released
 * as a unit after the base publishes. No steady index memory retains these counts (the final locator keeps the compact
 * bitmap/rank pages instead), and no Java object exists per node or page payload.
 */
final class LmdbAdjacencyBuildWorkspace implements AutoCloseable {

	private static final int TYPE_COUNT = 4;

	private static final long PAGE_BITMAP_BYTES = 512;

	private static final long PAGE_BYTES = PAGE_BITMAP_BYTES
			+ (long) LmdbReferenceNodeLocator.PAGE_SLOTS * LmdbReferenceNodeLocator.PLANE_COUNT * Integer.BYTES;

	private final LmdbAdjacencyMemoryAccount account;

	private final LmdbAdjacencyArena arena;

	private final long[][] pageRefs = new long[TYPE_COUNT][];

	private final long[] maxActivePayloadExclusive = new long[TYPE_COUNT];

	private long activeNodeCount;

	private long groupCount;

	private long chargedBytes;

	LmdbAdjacencyBuildWorkspace(LmdbAdjacencyMemoryAccount account, long[] payloadHighWaterExclusiveByType,
			long regionBytes) {
		if (payloadHighWaterExclusiveByType.length != TYPE_COUNT) {
			throw new IllegalArgumentException("expected one payload high water per reference type");
		}
		this.account = account;
		this.arena = new LmdbAdjacencyArena(regionBytes);
		for (int t = 0; t < TYPE_COUNT; t++) {
			long pageCount = (payloadHighWaterExclusiveByType[t] + LmdbReferenceNodeLocator.PAGE_SLOTS
					- 1) >>> LmdbReferenceNodeLocator.PAGE_SHIFT;
			if (pageCount > Integer.MAX_VALUE) {
				throw new IllegalArgumentException("build page directory exceeds the addressable bound: " + pageCount);
			}
			pageRefs[t] = new long[(int) pageCount];
		}
	}

	/**
	 * Marks {@code (type, payload)} active and increments its plane group count once per group (Pass 1).
	 */
	void recordGroup(int type, long payload, int plane) {
		int t = typeIndex(type);
		MemorySegment page = pageFor(t, payload, true);
		int slot = (int) (payload & (LmdbReferenceNodeLocator.PAGE_SLOTS - 1));
		long wordOffset = (long) (slot >>> 6) * 8;
		long word = page.get(LmdbAdjacencyArena.U64_LE, wordOffset);
		long bit = 1L << (slot & 63);
		if ((word & bit) == 0) {
			page.set(LmdbAdjacencyArena.U64_LE, wordOffset, word | bit);
			activeNodeCount++;
			if (payload + 1 > maxActivePayloadExclusive[t]) {
				maxActivePayloadExclusive[t] = payload + 1;
			}
		}
		long cellOffset = cellOffset(slot, plane);
		int count = page.get(LmdbAdjacencyArena.U32_LE, cellOffset);
		if (count == -1) {
			throw new IllegalStateException("plane group count overflowed u32");
		}
		page.set(LmdbAdjacencyArena.U32_LE, cellOffset, count + 1);
		groupCount++;
	}

	long count(int type, long payload, int plane) {
		MemorySegment page = pageFor(typeIndex(type), payload, false);
		if (page == null) {
			return 0;
		}
		return Integer.toUnsignedLong(
				page.get(LmdbAdjacencyArena.U32_LE, cellOffset((int) (payload & 0xfff), plane)));
	}

	long activeNodeCount() {
		return activeNodeCount;
	}

	long groupCount() {
		return groupCount;
	}

	/**
	 * The per-type maximum active payload plus one, measured by Pass 1; the final locator top arrays shrink to this.
	 */
	long maxActivePayloadExclusive(int type) {
		return maxActivePayloadExclusive[typeIndex(type)];
	}

	long chargedBytes() {
		return chargedBytes;
	}

	interface NodeVisitor {
		void node(int type, long payload, long[] planeCounts);
	}

	/**
	 * Visits every active node in ascending {@code (type, payload)} order with its four plane counts (Pass 2 walk).
	 */
	void forEachActiveNode(NodeVisitor visitor) {
		long[] planeCounts = new long[LmdbReferenceNodeLocator.PLANE_COUNT];
		for (int t = 0; t < TYPE_COUNT; t++) {
			long[] refs = pageRefs[t];
			for (int pageNo = 0; pageNo < refs.length; pageNo++) {
				if (refs[pageNo] == 0) {
					continue;
				}
				MemorySegment page = arena.slice(refs[pageNo], PAGE_BYTES);
				for (int word = 0; word < 64; word++) {
					long bits = page.get(LmdbAdjacencyArena.U64_LE, (long) word * 8);
					while (bits != 0) {
						int slot = (word << 6) + Long.numberOfTrailingZeros(bits);
						bits &= bits - 1;
						for (int p = 0; p < LmdbReferenceNodeLocator.PLANE_COUNT; p++) {
							planeCounts[p] = Integer.toUnsignedLong(
									page.get(LmdbAdjacencyArena.U32_LE, cellOffset(slot, p)));
						}
						visitor.node(t + ValueIds.T_URI, ((long) pageNo << LmdbReferenceNodeLocator.PAGE_SHIFT) + slot,
								planeCounts);
					}
				}
			}
		}
	}

	@Override
	public void close() {
		arena.close();
		if (chargedBytes > 0) {
			account.release(LmdbAdjacencyMemoryAccount.MemoryKind.BUILD_COUNTERS, chargedBytes);
			chargedBytes = 0;
		}
	}

	private MemorySegment pageFor(int t, long payload, boolean create) {
		long pageNo = payload >>> LmdbReferenceNodeLocator.PAGE_SHIFT;
		if (payload < 0 || pageNo >= pageRefs[t].length) {
			throw new IllegalArgumentException("payload beyond the declared high water: " + payload);
		}
		long ref = pageRefs[t][(int) pageNo];
		if (ref == 0) {
			if (!create) {
				return null;
			}
			if (!account.tryReserve(LmdbAdjacencyMemoryAccount.MemoryKind.BUILD_COUNTERS, PAGE_BYTES)) {
				throw new LmdbAdjacencyMemoryRefusedException("build counter page reservation refused");
			}
			chargedBytes += PAGE_BYTES;
			ref = arena.allocateRef(PAGE_BYTES, 8);
			pageRefs[t][(int) pageNo] = ref;
		}
		return arena.slice(ref, PAGE_BYTES);
	}

	private static long cellOffset(int slot, int plane) {
		return PAGE_BITMAP_BYTES + ((long) slot * LmdbReferenceNodeLocator.PLANE_COUNT + plane) * Integer.BYTES;
	}

	private static int typeIndex(int type) {
		if (type < ValueIds.T_URI || type > ValueIds.T_TRIPLE) {
			throw new IllegalArgumentException("not a reference type: " + type);
		}
		return type - ValueIds.T_URI;
	}
}
